package com.exito.chop;
import android.net.Uri;import android.os.SystemClock;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import org.json.*;
/** Explicit opt-in, personal-provider-key integration. No secrets included in project/history. */
final class AiCover {
 static final String HOST="https://api.stability.ai";static volatile boolean running,cancelled;static volatile HttpURLConnection connection;
 static void cancel(){cancelled=true;HttpURLConnection c=connection;if(c!=null)c.disconnect();}
 static HttpURLConnection open(String path,String key)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(HOST+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(20000);c.setReadTimeout(60000);c.setRequestProperty("Authorization","Bearer "+key);c.setRequestProperty("Accept","audio/*, application/json");connection=c;return c;}
 static String text(InputStream in)throws Exception{if(in==null)return "";try(InputStream input=in;ByteArrayOutputStream b=new ByteArrayOutputStream()){byte[] block=new byte[4096];int n;while((n=input.read(block))>0){if(b.size()+n>1024*1024)throw new IOException("Respuesta demasiado larga");b.write(block,0,n);}return b.toString("UTF-8");}}
 static IOException error(HttpURLConnection c)throws Exception{String body=text(c.getErrorStream());String reason="HTTP "+c.getResponseCode();try{JSONObject json=new JSONObject(body);if(json.has("errors"))reason+=" · "+json.getJSONArray("errors").optString(0);else reason+=" · "+json.optString("message",json.optString("name",""));}catch(Exception ignored){}return new IOException(reason);}
 static void generate(Engine e,String prompt,float strength,int duration,boolean whole){if(running||!e.ready()){e.message("Espera a que termine el proceso actual");return;}if(!whole&&!e.hasPad(e.selected)){e.message("Marca primero un pad.");return;}e.finishPadMarking(false);e.freezeForEdit();final short[] source=e.rendered;final int rate=e.rate;double scale=source.length/(double)e.source.length;final int from=whole?0:(int)(e.start(e.selected)*scale),to=whole?source.length/2:(int)(e.end(e.selected)*scale);running=true;cancelled=false;new Thread(()->{File input=null;try{String key=KeyStoreSecret.get(e.context);if(key.isEmpty())throw new IOException("Configura tu clave de Stability AI");int frames=to-from;if(frames/(double)rate>380)throw new IOException("La referencia supera 380 s. Selecciona un chop más corto.");int uploadFrames=Math.max(frames,rate*6);short[] pcm=new short[uploadFrames*2];for(int i=0;i<uploadFrames;i++){pcm[i*2]=source[(from+i%frames)*2];pcm[i*2+1]=source[(from+i%frames)*2+1];}input=File.createTempFile("exito-reference-",".wav",e.context.getCacheDir());try(OutputStream out=new BufferedOutputStream(new FileOutputStream(input))){AudioFiles.writeWav(out,pcm,rate);}e.message("IA · enviando referencia a Stability AI");String id=upload(input,key,prompt,strength,duration==0?uploadFrames/(double)rate:duration);e.context.getSharedPreferences("ai-private",0).edit().putString("pending",id).apply();poll(e,key,id);}catch(Throwable error){e.message(cancelled?"Se dejó de esperar. El proveedor puede continuar la generación; usa Recuperar pendiente.":"IA: "+Engine.reason(error));}finally{if(input!=null)input.delete();connection=null;running=false;}},"EXITO-AI").start();}
 static String upload(File input,String key,String prompt,float strength,double duration)throws Exception{String boundary="EXITO"+UUID.randomUUID().toString().replace("-","");LinkedHashMap<String,String> fields=new LinkedHashMap<>();fields.put("model","stable-audio-3");fields.put("prompt",prompt);fields.put("duration",String.format(Locale.US,"%.3f",duration));fields.put("strength",String.format(Locale.US,"%.3f",strength));fields.put("steps","8");fields.put("output_format","wav");ByteArrayOutputStream prefix=new ByteArrayOutputStream();for(Map.Entry<String,String> field:fields.entrySet())prefix.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\""+field.getKey()+"\"\r\n\r\n"+field.getValue()+"\r\n").getBytes(StandardCharsets.UTF_8));prefix.write(("--"+boundary+"\r\nContent-Disposition: form-data; name=\"audio\"; filename=\"reference.wav\"\r\nContent-Type: audio/wav\r\n\r\n").getBytes(StandardCharsets.UTF_8));byte[] end=("\r\n--"+boundary+"--\r\n").getBytes(StandardCharsets.UTF_8);HttpURLConnection c=open("/v2beta/audio/stable-audio/audio-to-audio",key);try{c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","multipart/form-data; boundary="+boundary);c.setFixedLengthStreamingMode(prefix.size()+input.length()+end.length);try(OutputStream out=c.getOutputStream();InputStream in=new FileInputStream(input)){prefix.writeTo(out);byte[] block=new byte[65536];int n;while((n=in.read(block))>0){if(cancelled)throw new IOException("Cancelado");out.write(block,0,n);}out.write(end);}if(c.getResponseCode()!=202)throw error(c);String id=new JSONObject(text(c.getInputStream())).getString("id");if(!id.matches("[A-Za-z0-9_-]{1,180}"))throw new IOException("Identificador de generación no válido");return id;}finally{c.disconnect();}}
 static void resume(Engine e){if(running)return;String id=e.context.getSharedPreferences("ai-private",0).getString("pending","");if(id.isEmpty()){e.message("No hay una generación pendiente");return;}running=true;cancelled=false;new Thread(()->{try{poll(e,KeyStoreSecret.get(e.context),id);}catch(Throwable error){e.message("IA: "+Engine.reason(error));}finally{running=false;connection=null;}},"EXITO-AI-resume").start();}
 static void poll(Engine e,String key,String id)throws Exception{long until=SystemClock.elapsedRealtime()+20*60*1000;while(SystemClock.elapsedRealtime()<until&&!cancelled){HttpURLConnection c=open("/v2beta/audio/results/"+id,key);try{int status=c.getResponseCode();if(status==202){text(c.getInputStream());e.message("IA · generación en curso · puedes seguir usando el sampler");}else if(status==200){String type=c.getContentType();if(type==null||!type.startsWith("audio/"))throw new IOException("El proveedor no devolvió audio");File dir=new File(e.context.getCacheDir(),"exports");dir.mkdirs();File result=new File(dir,"ChopGO_IA_"+System.currentTimeMillis()+".wav");try(InputStream in=c.getInputStream();OutputStream out=new BufferedOutputStream(new FileOutputStream(result))){long size=0;byte[] block=new byte[65536];int n;while((n=in.read(block))>0){if(cancelled)throw new IOException("Cancelado");size+=n;if(size>100*1024*1024)throw new IOException("Resultado demasiado grande");out.write(block,0,n);}}e.context.getSharedPreferences("ai-private",0).edit().remove("pending").apply();e.main.post(()->{if(!e.busy&&!e.capturing){e.slots.save();for(int i=0;i<8;i++)if(e.slots.list[i].source==null){e.slots.activate(i);e.importAudio(Uri.fromFile(result));break;}}MainActivity.launch(e.context,"save-artifact",result.getName());});return;}else throw error(c);}finally{c.disconnect();}Thread.sleep(2500);}throw new IOException(cancelled?"Espera cancelada; puedes recuperar la generación":"Tiempo de espera agotado; usa Recuperar pendiente");}
}
